const { writeFileSync, mkdirSync, existsSync } = await import('node:fs');
const path = await import('node:path');
globalThis.inputPath = process.env.INPUT_PATH;
globalThis.outputPath = process.env.OUTPUT_PATH;
if (!globalThis.inputPath || !globalThis.outputPath) { throw new Error('Missing required env vars'); }
if (!existsSync(globalThis.inputPath)) { writeFileSync(globalThis.inputPath, ''); }
const outDir = path.dirname(globalThis.outputPath);
if (!existsSync(outDir)) { mkdirSync(outDir, { recursive: true }); }

const mod = await import('docx2pdf-converter');
const topdf = mod.default || mod;
if (typeof topdf.convert !== 'function') { throw new Error('convert function not found'); }
// The convert API is synchronous; wrap in try/catch for safety
try {
  topdf.convert(globalThis.inputPath, globalThis.outputPath);
} catch (e) {
  throw new Error('Conversion failed: ' + e.message);
}
